def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    bg = grid[0][0]  # Background color

    # Find separator (2s line)
    sep_pos = -1
    sep_type = None  # 'row' or 'col'

    for r in range(rows):
        if all(grid[r][c] == 2 for c in range(cols)):
            sep_pos = r
            sep_type = 'row'
            break

    for c in range(cols):
        if all(grid[r][c] == 2 for r in range(rows)):
            sep_pos = c
            sep_type = 'col'
            break

    # Find pattern color
    pat_color = None
    pat_rows = []
    pat_cols = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg and grid[r][c] != 2:
                pat_color = grid[r][c]
                pat_rows.append(r)
                pat_cols.append(c)

    # Build output
    output = [[bg for _ in range(cols)] for _ in range(rows)]

    # Place separator
    if sep_type == 'row':
        for c in range(cols):
            output[sep_pos][c] = 2
    else:
        for r in range(rows):
            output[r][sep_pos] = 2

    # Place pattern (preserve original positions)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == pat_color:
                output[r][c] = pat_color

    # Place 8s line based on pattern position relative to separator
    if sep_type == 'col':  # Vertical separator
        if pat_cols:
            min_c = min(pat_cols)
            max_c = max(pat_cols)
            if max_c > sep_pos:  # Pattern right of separator
                pos = max_c + 1
                if pos < cols:
                    for r in range(rows):
                        output[r][pos] = 8
            elif min_c < sep_pos:  # Pattern left of separator
                pos = min_c - 1
                if pos >= 0:
                    for r in range(rows):
                        output[r][pos] = 8

    elif sep_type == 'row':  # Horizontal separator
        if pat_rows:
            min_r = min(pat_rows)
            max_r = max(pat_rows)
            if max_r > sep_pos:  # Pattern below separator
                pos = max_r + 1
                if pos < rows:
                    for c in range(cols):
                        output[pos][c] = 8
            elif min_r < sep_pos:  # Pattern above separator
                pos = min_r - 1
                if pos >= 0:
                    for c in range(cols):
                        output[pos][c] = 8

    return output
